/bin/zsh -lc "node --input-type=module <<'NODE'
import { readFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
for (const file of ['engineering-baseline.md', 'CONTEXT.md', 'scripts/lib/api-contract-decision.mjs', 'scripts/lib/api-contract-decision.test.mjs']) {
  console.log(file + ' sha256:' + createHash('sha256').update(readFileSync(file)).digest('hex'));
}
NODE"

/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync, readdirSync } from 'node:fs';
import { createHash } from 'node:crypto';
const report = JSON.parse(readFileSync('api-check.json', 'utf8'));
assert.equal(report.command, 'node --test scripts/lib/api-contract-decision.test.mjs');
assert.equal(report.exit_code, 0);
assert.ok(Array.isArray(report.limitations) && report.limitations.length > 0);
for (const [file, digest] of [['scripts/lib/api-contract-decision.test.mjs', report.test_source_digest], ['scripts/lib/api-contract-decision.mjs', report.validator_source_digest]]) {
  assert.equal('sha256:' + createHash('sha256').update(readFileSync(file)).digest('hex'), digest);
}
const plan = readFileSync('technical-plan.md', 'utf8');
assert.ok(plan.includes('layered-mvc') && plan.includes('impact: required') && plan.includes('api-check.json'));
assert.equal(readdirSync('.').filter(name => name.startsWith('api-contract-decision-')).length, 0);
console.log('产物读取、JSON 字段、测试来源摘要及临时目录清理检查通过。');
NODE"
